"""Compute the winner of a game of Hex / Polygon (Connect).

The board is given as lines of text where each cell is a single
character (``X``, ``O`` or ``.``) separated by spaces.  Each row is
indented one extra space per row index so that the parallelogram is
drawn in a skewed layout.

Player ``X`` plays from left to right, player ``O`` plays from top to
bottom.  A player wins as soon as their stones form a connected path
between their two assigned sides.
"""

from collections import deque


class ConnectGame:
    # The six neighbours of a cell in the skewed board layout.
    _NEIGHBOURS = ((0, -1), (0, 1), (-1, 0), (-1, 1), (1, -1), (1, 0))

    def __init__(self, board):
        self.board = [
            line.strip().split()
            for line in board.strip().splitlines()
        ]

    def get_winner(self):
        if self._wins("X"):
            return "X"
        if self._wins("O"):
            return "O"
        return ""

    def _wins(self, player):
        rows = len(self.board)
        if rows == 0:
            return False
        cols = [len(row) for row in self.board]

        if player == "X":
            # X plays from left to right.
            seeds = [
                (r, 0)
                for r in range(rows)
                if cols[r] > 0 and self.board[r][0] == player
            ]

            def on_target(r, c):
                return c == cols[r] - 1
        else:
            # O plays from top to bottom.
            seeds = [(0, c) for c in range(cols[0]) if self.board[0][c] == player]

            def on_target(r, c):
                return r == rows - 1

        seen = set(seeds)
        queue = deque(seeds)
        while queue:
            r, c = queue.popleft()
            if on_target(r, c):
                return True
            for dr, dc in self._NEIGHBOURS:
                nr, nc = r + dr, c + dc
                if (
                    0 <= nr < rows
                    and 0 <= nc < cols[nr]
                    and (nr, nc) not in seen
                    and self.board[nr][nc] == player
                ):
                    seen.add((nr, nc))
                    queue.append((nr, nc))
        return False

